      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not distinguish exclusions due to outcomes not being measured versus exclusions due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although interventions and network comparisons are mentioned (e.g., SUCRA rankings for specific plant extracts vs conventional treatment), the evidence does not specify the groups used in each synthesis or link them to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "It should be noted that this search was restricted to published literature. Therefore, citation tracking was not performed, and clinical trial registries such as ClinicalTrials.gov or the Chinese Clinical Trial Registry (ChiCTR) were not searched.",
      "reason": "A rationale is provided for a notable restriction (search restricted to published literature) and related exclusions of citation tracking and trial registry searching, but no rationales are provided for other notable eligibility restrictions."
    }
  ],
  "confidence": 66
}

